// helper function to multiply two numbers
int multiply(int first_number, int second_number) {
    // multiply the two numbers together
    int product = ((first_number) * (second_number));
    // return the multiplication result to the caller
    return (product);
}

// main required function for returning n factorial
int factorial(int n) {
    // get the factorial of the number that is one smaller
    int smaller_factorial = factorial((n - 1));
    // multiply n by the smaller factorial to find the answer
    return (multiply(n, smaller_factorial));
}
